def check(inp, out, minr, majr):
    H=len(inp); W=len(inp[0]); errs=[]
    for r in range(H):
        for c in range(W):
            x=inp[r][c]; y=out[r][c]
            if x==minr or x==0 and minr!=0: pass
            if x==minr:
                if y!=x: errs.append((r,c,'minority changed'))
            elif x==majr:
                rb=any(inp[r][j]==minr for j in range(c)) and any(inp[r][j]==minr for j in range(c+1,W))
                cb=any(inp[i][c]==minr for i in range(r)) and any(inp[i][c]==minr for i in range(r+1,H))
                pred=3 if (rb or cb) else x
                if y!=pred: errs.append((r,c,f'pred {pred} got {y}'))
            else:
                if y!=x: errs.append((r,c,'bg changed'))
    return errs
